pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 callCount) public {
        callCount = uint8(bound(callCount, 1, 20));
        for (uint8 i = 0; i < callCount; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            try c.play{value: 10}() {} catch {}
        }
        assertTrue(c.pot() != 1);
    }
}
